1	// Shared helpers for the server tests: spawn server.mjs, send raw HTTP requests.
2	import { spawn } from 'node:child_process';
3	import http from 'node:http';
4	import fs from 'node:fs';
5	import os from 'node:os';
6	import path from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	import net from 'node:net';
9	
10	export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
11	export const SERVER = path.join(ROOT, 'server.mjs');
12	const LISTEN_LINE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
13	
14	/** A fresh empty temp folder, removed with the returned cleanup. */
15	export function makeTempDir() {
16	  return fs.mkdtempSync(path.join(os.tmpdir(), 'rooms-test-'));
17	}
18	
19	/** process.env without PORT/DATA_FILE, then `env` applied (an undefined value removes the key). */
20	function buildEnv(env) {
21	  const base = { ...process.env };
22	  delete base.PORT;
23	  delete base.DATA_FILE;
24	  const merged = { ...base, ...env };
25	  return Object.fromEntries(Object.entries(merged).filter(([, v]) => v !== undefined));
26	}
27	
28	function spawnServer({ env = {}, cwd = ROOT } = {}) {
29	  const child = spawn(process.execPath, [SERVER], { cwd, env: buildEnv(env), stdio: ['ignore', 'pipe', 'pipe'] });
30	  const out = { stdout: '', stderr: '' };
31	  child.stdout.setEncoding('utf8').on('data', (d) => { out.stdout += d; });
32	  child.stderr.setEncoding('utf8').on('data', (d) => { out.stderr += d; });
33	  const exited = new Promise((resolve) => child.on('close', (code, signal) => resolve({ code, signal })));
34	  return { child, out, exited };
35	}
36	
37	/** Runs the server expecting it to exit by itself; resolves { code, stdout, stderr }. */
38	export async function runToExit({ env, cwd, timeoutMs = 5000 } = {}) {
39	  const { child, out, exited } = spawnServer({ env, cwd });
40	  const timer = setTimeout(() => child.kill('SIGKILL'), timeoutMs);
41	  const { code, signal } = await exited;
42	  clearTimeout(timer);
43	  return { code, signal, stdout: out.stdout, stderr: out.stderr };
44	}
45	
46	/**
47	 * Starts the server (PORT=0 unless given) and waits for its listening line.
48	 * Returns { port, child, stdout(), stderr(), stop() }; stop() kills it and resolves on exit.
49	 */
50	export async function startServer({ env = {}, cwd } = {}) {
51	  const { child, out, exited } = spawnServer({ env: { PORT: '0', ...env }, cwd });
52	  const port = await new Promise((resolve, reject) => {
53	    const timer = setTimeout(() => reject(new Error(`server did not start: ${out.stderr}`)), 5000);
54	    const onData = () => {
55	      const match = LISTEN_LINE.exec(out.stdout);
56	      if (match) {
57	        clearTimeout(timer);
58	        child.stdout.off('data', onData);
59	        resolve(Number(match[1]));
60	      }
61	    };
62	    child.stdout.on('data', onData);
63	    exited.then(({ code }) => {
64	      clearTimeout(timer);
65	      reject(new Error(`server exited early (code ${code}): ${out.stderr}`));
66	    });
67	  });
68	  return {
69	    port,
70	    child,
71	    stdout: () => out.stdout,
72	    stderr: () => out.stderr,
73	    exited,
74	    stop: async () => {
75	      if (child.exitCode === null && child.signalCode === null) child.kill('SIGTERM');
76	      return exited;
77	    },
78	  };
79	}
80	
81	/**
82	 * Sends one request with the request target written exactly as `target`.
83	 * `body` may be a string or Buffer. Resolves { status, headers, raw (Buffer), text, json }.
84	 * `json` is the parsed body, or undefined when the body is empty or not JSON.
85	 */
86	export function request(port, { method = 'GET', target = '/', headers = {}, body } = {}) {
87	  return new Promise((resolve, reject) => {
88	    const req = http.request({ host: '127.0.0.1', port, method, path: target, headers, agent: false });
89	    req.on('error', reject);
90	    req.on('response', (res) => {
91	      const chunks = [];
92	      res.on('data', (c) => chunks.push(c));
93	      res.on('error', reject);
94	      res.on('end', () => {
95	        const raw = Buffer.concat(chunks);
96	        const text = raw.toString('utf8');
97	        let json;
98	        try { json = JSON.parse(text); } catch { json = undefined; }
99	        resolve({ status: res.statusCode, headers: res.headers, raw, text, json });
100	      });
101	    });
102	    if (body !== undefined) req.write(body);
103	    req.end();
104	  });
105	}
106	
107	export const JSON_CT = 'application/json; charset=utf-8';
108	
109	/** POSTs a booking object as JSON with `Content-Type: application/json`. */
110	export function postBooking(port, booking, headers = { 'Content-Type': 'application/json' }) {
111	  return request(port, { method: 'POST', target: '/api/bookings', headers, body: JSON.stringify(booking) });
112	}
113	
114	export const FIXTURE_BOOKING = { id: 2, room: 'Aurora', title: 'T', date: '2026-11-03', start: '09:00', end: '10:00' };
115	export const FIXTURE = JSON.stringify({ nextId: 5, bookings: [FIXTURE_BOOKING] });
116	
117	/** A temp folder removed automatically after the test `t`. */
118	export function tmp(t) {
119	  const dir = makeTempDir();
120	  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
121	  return dir;
122	}
123	
124	export const listeningLine = (port) => `listening on http://127.0.0.1:${port}\n`;
125	
126	function parseRawReply(buf) {
127	  const split = buf.indexOf('\r\n\r\n');
128	  if (split < 0) throw new Error(`no header end in reply: ${JSON.stringify(buf.toString('latin1'))}`);
129	  const [statusLine, ...lines] = buf.subarray(0, split).toString('latin1').split('\r\n');
130	  const match = /^HTTP\/1\.[01] (\d{3}) /.exec(statusLine);
131	  if (!match) throw new Error(`bad status line: ${JSON.stringify(statusLine)}`);
132	  const headers = {};
133	  for (const line of lines) {
134	    const i = line.indexOf(':');
135	    headers[line.slice(0, i).toLowerCase()] = line.slice(i + 1).trim();
136	  }
137	  return { status: Number(match[1]), headers, body: buf.subarray(split + 4).toString('utf8') };
138	}
139	
140	/**
141	 * Writes `bytes` to a raw TCP socket and reads the reply until the server closes it.
142	 * Resolves { status, headers (lower-cased names), body (string) }.
143	 */
144	export function rawRequest(port, bytes) {
145	  return new Promise((resolve, reject) => {
146	    const chunks = [];
147	    const socket = net.connect(port, '127.0.0.1', () => socket.write(bytes));
148	    socket.on('data', (c) => chunks.push(c));
149	    socket.on('error', reject);
150	    socket.on('close', () => {
151	      try { resolve(parseRawReply(Buffer.concat(chunks))); } catch (err) { reject(err); }
152	    });
153	  });
154	}
155	
156	/** A valid booking body; override fields as needed. */
157	export function booking(overrides = {}) {
158	  return { room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00', ...overrides };
159	}
