1	import { readFileSync } from 'node:fs';
2	import vm from 'node:vm';
3	import { fileURLToPath } from 'node:url';
4	
5	const APP_PATH = fileURLToPath(new URL('../../public/app.js', import.meta.url));
6	const IDS = [
7	  'booking-form', 'room', 'title', 'date', 'start', 'end', 'book',
8	  'error', 'filter-date', 'show-all', 'booking-list'
9	];
10	// Members the page script may touch (plus test-only ones).
11	const ALLOWED = new Set([
12	  'textContent', 'value', 'type', 'disabled', 'append', 'replaceChildren',
13	  'addEventListener', 'children', 'tagName', 'dispatch', 'listeners', 'id'
14	]);
15	
16	function textNode(text) {
17	  return { nodeType: 3, textContent: String(text) };
18	}
19	
20	function toNodes(nodes) {
21	  return nodes.map((n) => (typeof n === 'string' ? textNode(n) : n));
22	}
23	
24	class FakeElement {
25	  constructor(tag, id, log) {
26	    this.tagName = tag.toUpperCase();
27	    this.id = id;
28	    this.children = [];
29	    this.type = '';
30	    this._text = '';
31	    this._value = '';
32	    this._disabled = false;
33	    this._listeners = new Map();
34	    this._log = log;
35	  }
36	
37	  get label() {
38	    return this.id || this.tagName;
39	  }
40	
41	  get textContent() {
42	    if (this.children.length > 0) return this.children.map((c) => c.textContent).join('');
43	    return this._text;
44	  }
45	
46	  set textContent(text) {
47	    this.children = [];
48	    this._text = String(text);
49	    if (this.id === 'error') this._log.push(['textContent', this.id, this._text]);
50	  }
51	
52	  get value() { return this._value; }
53	
54	  set value(v) {
55	    this._value = v;
56	    this._log.push(['value', this.label, v]);
57	  }
58	
59	  get disabled() { return this._disabled; }
60	
61	  set disabled(v) {
62	    this._disabled = v;
63	    this._log.push(['disabled', this.label, v]);
64	  }
65	
66	  append(...nodes) {
67	    this.children = [...this.children, ...toNodes(nodes)];
68	  }
69	
70	  replaceChildren(...nodes) {
71	    this._log.push(['replaceChildren', this.label]);
72	    this.children = toNodes(nodes);
73	    this._text = '';
74	  }
75	
76	  addEventListener(type, fn) {
77	    const list = this._listeners.get(type) || [];
78	    this._listeners.set(type, [...list, fn]);
79	  }
80	
81	  listeners(type) {
82	    return [...(this._listeners.get(type) || [])];
83	  }
84	
85	  listenerTypes() {
86	    return [...this._listeners.keys()].filter((t) => this._listeners.get(t).length > 0);
87	  }
88	
89	  dispatch(type, event) {
90	    return this.listeners(type).map((fn) => fn(event));
91	  }
92	}
93	
94	// Proxy enforcing the allow-list of members; symbols pass through.
95	function guard(el) {
96	  return new Proxy(el, {
97	    get(target, prop) {
98	      if (typeof prop === 'symbol') return undefined;
99	      if (prop === 'listenerTypes') return target.listenerTypes.bind(target);
100	      if (!ALLOWED.has(prop)) throw new Error(`Disallowed element member read: ${prop}`);
101	      const v = Reflect.get(target, prop, target);
102	      return typeof v === 'function' ? v.bind(target) : v;
103	    },
104	    set(target, prop, value) {
105	      if (!ALLOWED.has(prop)) throw new Error(`Disallowed element member write: ${String(prop)}`);
106	      return Reflect.set(target, prop, value, target);
107	    }
108	  });
109	}
110	
111	export function createFakeDom() {
112	  const log = [];
113	  const elements = {};
114	  for (const id of IDS) elements[id] = guard(new FakeElement('div', id, log));
115	  const document = {
116	    getElementById: (id) => (Object.hasOwn(elements, id) ? elements[id] : null),
117	    createElement: (tag) => guard(new FakeElement(tag, '', log))
118	  };
119	  return { document, elements, log };
120	}
121	
122	export function createFakeFetch(log = []) {
123	  const calls = [];
124	  const fetch = (...args) => {
125	    const call = { url: args[0], options: args[1], argCount: args.length, jsonCalls: 0, settled: false };
126	    calls.push(call);
127	    log.push(['fetch', args[0]]);
128	    return new Promise((resolve, reject) => {
129	      call.resolve = resolve;
130	      call.reject = reject;
131	    });
132	  };
133	  const settle = (call, fn) => {
134	    call.settled = true;
135	    fn();
136	  };
137	  return {
138	    fetch,
139	    calls,
140	    respond(call, status, body) {
141	      settle(call, () => call.resolve({
142	        status,
143	        json: () => { call.jsonCalls += 1; return Promise.resolve(body); }
144	      }));
145	    },
146	    respondRaw(call, status, jsonImpl) {
147	      settle(call, () => call.resolve({
148	        status,
149	        json: () => { call.jsonCalls += 1; return jsonImpl(); }
150	      }));
151	    },
152	    fail(call) {
153	      settle(call, () => call.reject(new TypeError('fetch failed')));
154	    }
155	  };
156	}
