1	// Startup behaviour of server.mjs: PORT checks, data file reading, order, no writes.
2	import { test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import fs from 'node:fs';
5	import net from 'node:net';
6	import path from 'node:path';
7	import {
8	  startServer, runToExit, request, postBooking, booking, ROOT, FIXTURE, FIXTURE_BOOKING, tmp, listeningLine,
9	} from './helpers/server.mjs';
10	
11	function listen(port = 0) {
12	  return new Promise((resolve, reject) => {
13	    const srv = net.createServer();
14	    srv.once('error', reject);
15	    srv.listen(port, '127.0.0.1', () => resolve(srv));
16	  });
17	}
18	
19	const closeServer = (srv) => new Promise((resolve) => srv.close(resolve));
20	
21	async function freePort() {
22	  const srv = await listen();
23	  const { port } = srv.address();
24	  await closeServer(srv);
25	  return port;
26	}
27	
28	function assertOneLine(stderr) {
29	  assert.ok(stderr.endsWith('\n'), `stderr must end with newline: ${JSON.stringify(stderr)}`);
30	  const body = stderr.slice(0, -1);
31	  assert.ok(body.length > 0, 'stderr line must not be empty');
32	  assert.ok(!body.includes('\n'), `stderr must be one line: ${JSON.stringify(stderr)}`);
33	}
34	
35	function assertFailed(res, stderr) {
36	  assert.equal(res.code, 1);
37	  assert.equal(res.stdout, '');
38	  if (stderr === undefined) assertOneLine(res.stderr);
39	  else assert.equal(res.stderr, stderr);
40	}
41	
42	async function withServer(t, opts) {
43	  const srv = await startServer(opts);
44	  t.after(() => srv.stop());
45	  return srv;
46	}
47	
48	// ---- PORT ----
49	
50	const BAD_PORTS = ['abc', '+1', ' 80', '80 ', '1e3', '0x10', '65536', '99999999999999999999', '８０', '-1', '80\n'];
51	for (const port of BAD_PORTS) {
52	  test(`invalid PORT ${JSON.stringify(port)} exits 1 with one stderr line`, async (t) => {
53	    const dir = tmp(t);
54	    assertFailed(await runToExit({ env: { PORT: port }, cwd: dir }));
55	  });
56	}
57	
58	test('PORT in use exits 1 with one stderr line', async (t) => {
59	  const blocker = await listen();
60	  t.after(() => closeServer(blocker));
61	  const dir = tmp(t);
62	  const res = await runToExit({ env: { PORT: String(blocker.address().port) }, cwd: dir });
63	  assertFailed(res);
64	});
65	
66	test('PORT is checked before the data file', async (t) => {
67	  const dir = tmp(t);
68	  fs.mkdirSync(path.join(dir, 'dir1'));
69	  const res = await runToExit({ env: { PORT: 'abc', DATA_FILE: 'dir1' }, cwd: dir });
70	  assert.equal(res.code, 1);
71	  assert.equal(res.stdout, '');
72	  assert.notEqual(res.stderr, 'cannot read data file dir1\n');
73	  assertOneLine(res.stderr);
74	});
75	
76	test('data file is read before listening', async (t) => {
77	  const blocker = await listen();
78	  t.after(() => closeServer(blocker));
79	  const dir = tmp(t);
80	  fs.mkdirSync(path.join(dir, 'dir1'));
81	  const res = await runToExit({ env: { PORT: String(blocker.address().port), DATA_FILE: 'dir1' }, cwd: dir });
82	  assertFailed(res, 'cannot read data file dir1\n');
83	});
84	
85	test('PORT=0 prints the bound port and serves requests', async (t) => {
86	  const dir = tmp(t);
87	  const srv = await withServer(t, { env: { PORT: '0' }, cwd: dir });
88	  assert.ok(srv.port > 0);
89	  assert.equal(srv.stdout(), listeningLine(srv.port));
90	  const res = await request(srv.port, { target: '/api/rooms' });
91	  assert.equal(res.status, 200);
92	  assert.deepEqual(res.json, { rooms: ['Aurora', 'Borealis', 'Cosmos'] });
93	});
94	
95	test('PORT=00 is accepted', async (t) => {
96	  const dir = tmp(t);
97	  const srv = await withServer(t, { env: { PORT: '00' }, cwd: dir });
98	  assert.ok(srv.port > 0);
99	  assert.equal(srv.stdout(), listeningLine(srv.port));
100	});
101	
102	test('PORT with leading zeros is accepted', async (t) => {
103	  const dir = tmp(t);
104	  const free = await freePort();
105	  const srv = await withServer(t, { env: { PORT: `0${free}` }, cwd: dir });
106	  assert.equal(srv.port, free);
107	  assert.equal(srv.stdout(), listeningLine(free));
108	});
109	
110	for (const [label, value] of [['unset', undefined], ['empty', '']]) {
111	  test(`PORT ${label} means 3000`, async (t) => {
112	    let probe;
113	    try {
114	      probe = await listen(3000);
115	    } catch (err) {
116	      if (err.code !== 'EADDRINUSE') throw err;
117	      t.skip('127.0.0.1:3000 is busy');
118	      return;
119	    }
120	    await closeServer(probe);
121	    const dir = tmp(t);
122	    const srv = await withServer(t, { env: { PORT: value }, cwd: dir });
123	    assert.equal(srv.port, 3000);
124	    assert.equal(srv.stdout(), listeningLine(3000));
125	  });
126	}
