128	// ---- DATA_FILE location ----
129	
130	for (const [label, value] of [['unset', undefined], ['empty', '']]) {
131	  test(`DATA_FILE ${label} defaults to bookings.json in the cwd`, async (t) => {
132	    const rootFile = path.join(ROOT, 'bookings.json');
133	    const existedBefore = fs.existsSync(rootFile);
134	    const dir = tmp(t);
135	    const srv = await withServer(t, { env: { DATA_FILE: value }, cwd: dir });
136	    const res = await postBooking(srv.port, booking());
137	    assert.equal(res.status, 201);
138	    const saved = JSON.parse(fs.readFileSync(path.join(dir, 'bookings.json'), 'utf8'));
139	    assert.equal(typeof saved, 'object');
140	    assert.deepEqual(fs.readdirSync(dir), ['bookings.json']);
141	    if (!existedBefore) assert.equal(fs.existsSync(rootFile), false);
142	  });
