145	test('relative DATA_FILE is resolved against the cwd', async (t) => {
146	  const dir = tmp(t);
147	  fs.mkdirSync(path.join(dir, 'sub'));
148	  const srv = await withServer(t, { env: { DATA_FILE: 'sub/data.json' }, cwd: dir });
