155	
156	test('missing data file starts with no bookings and is not created', async (t) => {
157	  const dir = tmp(t);
158	  const srv = await withServer(t, { env: { DATA_FILE: 'data.json' }, cwd: dir });
159	  const res = await request(srv.port, { target: '/api/bookings' });
