150	function sendChunked(port, headers, chunkCount, chunkSize) {
151	  return new Promise((resolve, reject) => {
152	    const req = http.request({ host: '127.0.0.1', port, method: 'POST', path: '/api/bookings', headers, agent: false });
153	    req.on('error', reject);
154	    req.on('response', (res) => {
155	      const parts = [];
156	      res.on('data', (c) => parts.push(c));
157	      res.on('error', reject);
158	      res.on('end', () => {
159	        try {
160	          resolve({ status: res.statusCode, json: JSON.parse(Buffer.concat(parts).toString('utf8')) });
161	        } catch (err) {
162	          reject(err);
163	        }
164	      });
165	    });
166	    const chunks = Array.from({ length: chunkCount }, () => Buffer.alloc(chunkSize, 0x61));
167	    Readable.from(chunks).pipe(req);
168	  });
169	}
