171	test('413 and 415 replies reach the client after big bodies', async (t) => {
172	  const srv = await launch(t, path.join(tmp(t), 'd.json'));
173	  const big = Buffer.alloc(2_000_000, 0x61);
174	  const tooLarge = await request(srv.port, { method: 'POST', target: '/api/bookings', headers: { 'Content-Type': 'application/json' }, body: big });
175	  assert.equal(tooLarge.status, 413);
176	  assert.deepEqual(tooLarge.json, { error: 'body too large' });
177	  const wrongType = await request(srv.port, { method: 'POST', target: '/api/bookings', headers: { 'Content-Type': 'text/plain' }, body: big });
178	  assert.equal(wrongType.status, 415);
179	  assert.deepEqual(wrongType.json, { error: 'content type must be application/json' });
180	
181	  const chunkedLarge = await sendChunked(srv.port, { 'Content-Type': 'application/json' }, 200, 10000);
182	  assert.equal(chunkedLarge.status, 413);
183	  assert.deepEqual(chunkedLarge.json, { error: 'body too large' });
184	  const chunkedType = await sendChunked(srv.port, { 'Content-Type': 'text/plain' }, 200, 10000);
185	  assert.equal(chunkedType.status, 415);
186	  assert.deepEqual(chunkedType.json, { error: 'content type must be application/json' });
187	
188	  const body = Buffer.alloc(1_000_000, 0x61);
189	  const rooms = await request(srv.port, { target: '/api/rooms', headers: { 'Content-Length': String(body.length) }, body });
190	  assert.equal(rooms.status, 200);
191	  assert.deepEqual(rooms.json, { rooms: ['Aurora', 'Borealis', 'Cosmos'] });
192	  assert.equal(srv.child.exitCode, null);
