206	// Remove comments and string/template literals; also collect literal contents.
207	function stripCode(src) {
208	  let code = '';
209	  const literals = [];
210	  let i = 0;
211	  while (i < src.length) {
212	    const c = src[i];
213	    const n = src[i + 1];
214	    if (c === '/' && n === '/') {
215	      while (i < src.length && src[i] !== '\n') i++;
216	    } else if (c === '/' && n === '*') {
217	      const end = src.indexOf('*/', i + 2);
218	      i = end === -1 ? src.length : end + 2;
219	    } else if (c === '"' || c === "'" || c === '`') {
220	      let j = i + 1;
221	      while (j < src.length && src[j] !== c) j += src[j] === '\\' ? 2 : 1;
222	      literals.push(src.slice(i + 1, j));
223	      code += '""';
224	      i = j + 1;
225	    } else {
226	      code += c;
227	      i++;
228	    }
229	  }
230	  return { code, literals };
231	}
232	
